/* ASCENSION · expansión profunda de la academia.
   Contenido educativo original. Las preguntas son de comprensión conceptual, no tests clínicos. */
(function(){
 const branchMap={
  english:["Speaking y fluidez","Gramática y precisión","Comprensión y vocabulario"],
  japanese:["Escritura y lectura","Gramática básica","Conversación y escucha"],
  german:["Gramática y casos","Vocabulario y lectura","Conversación"],
  marketing:["Estrategia y mercado","Marca y creatividad","Analítica y campañas"],
  web:["Estructura y accesibilidad","Diseño de interfaz","Desarrollo y publicación"],
  reasoning:["Lógica y argumentos","Probabilidad y evidencia","Análisis de problemas"],
  organization:["Planificación","Atención y foco","Hábitos y aprendizaje"],
  commerce:["Atención y venta","Merchandising","Operaciones comerciales"],
  professional:["Portfolio y marca personal","Freelance y clientes","Carrera digital"],
  fitness:["Fuerza y programación","Recuperación y salud","Movilidad y técnica"],
  psychology:["Fundamentos y método","Cognición y emoción","Personalidad y vínculos","Salud mental"]
 };
 Object.entries(branchMap).forEach(([id,names])=>(LESSONS[id]?.units||[]).forEach((u,i)=>{u.branch=names[Math.min(names.length-1,Math.floor(i/2))];u.subbranch=u.branch+' · Profundización'}));
 function add(id,title,branch,objective,concepts,explain,example,steps,task,research,q,correct,wrong1,wrong2){
  const unit={title,branch,subbranch:branch+' · Núcleo y práctica',time:18,xp:35,objective,concepts,explain,example,steps,task,research};
  const index=LESSONS[id].units.push(unit)-1,key=id+"-"+index;
  const choices=[correct,wrong1,wrong2];
  LESSON_CHECKS[key]=[
   {q:q||"¿Qué idea describe mejor esta lección?",o:choices,a:0,e:"La respuesta correcta expresa el concepto central y sus límites."},
   {q:"¿Qué opción aplica mejor este principio a un caso real?",o:[wrong2,correct,wrong1],a:1,e:"Aplicar el concepto requiere distinguirlo de las dos confusiones habituales."},
   {q:"¿Qué error conviene evitar al trabajar este tema?",o:[wrong1,wrong2,correct],a:2,e:"La opción correcta evita la simplificación y mantiene el criterio de la lección."}
  ];
 }
 function route(id,name,icon){LESSONS[id]={name,icon,units:[]}}
 route("philosophy","Filosofía · Pensamiento y existencia","Φ");
 add("philosophy","Pensar con rigor: tesis y objeciones","Fundamentos","Convertir intuiciones en tesis claras y someterlas a objeciones razonables.","Tesis · concepto · argumento · objeción · definición · contraejemplo.","Filosofar no es coleccionar frases profundas. Es aclarar conceptos, preguntar qué damos por supuesto y comprobar si nuestras razones sostienen una conclusión. Una tesis debe poder explicarse y exponerse a objeciones. La mejor objeción no es la más fácil de desmontar, sino la que obliga a afinar la idea.","Pregunta: «¿Ser libre es hacer lo que quiero?». Antes de responder, distingue deseo, elección, autonomía y consecuencias.","1. Formula la pregunta.\n2. Define términos.\n3. Propón una tesis.\n4. Da razones.\n5. Construye la objeción más fuerte.","Escribe una tesis de 3-5 frases sobre qué significa vivir con autenticidad y añade una objeción que realmente la ponga a prueba.","philosophical argument thesis objections conceptual analysis","¿Qué convierte una opinión en una tesis filosófica argumentada?","Una afirmación clara apoyada en razones y abierta a objeciones.","Que suene misteriosa o profunda.","Que coincida con un autor famoso.","");
 add("philosophy","Validez, verdad y solidez","Lógica y argumentación","Distinguir la validez de la forma lógica de la verdad de las premisas.","Premisas · conclusión · validez · verdad · solidez · contraejemplo.","Un argumento es válido si, suponiendo verdaderas sus premisas, la conclusión no puede ser falsa. Es sólido si además las premisas son verdaderas. Forma lógica y verdad factual son preguntas distintas. Un razonamiento puede tener forma válida y partir de una premisa falsa.","Todos los dragones vuelan. Smaug es un dragón. Por tanto, Smaug vuela: la forma es válida, pero la premisa sobre dragones no queda demostrada.","1. Separa premisas y conclusión.\n2. Prueba la forma.\n3. Evalúa las premisas.\n4. Busca contraejemplos.\n5. Decide si es sólido.","Construye un argumento válido con una premisa falsa y explica por qué no es sólido.","logic validity soundness premises conclusion philosophy","¿Qué añade la solidez a la validez?","Que las premisas sean verdaderas además de la forma válida.","Que la conclusión sea popular.","Que el argumento tenga muchas premisas.","");
 add("philosophy","Conocimiento, evidencia y escepticismo","Epistemología","Examinar qué justifica una creencia y qué límites tienen nuestras fuentes de conocimiento.","Epistemología · evidencia · justificación · fiabilidad · escepticismo.","No basta con creer algo ni con acertar por casualidad para decir que lo sabemos. Percepción, memoria, testimonio y razonamiento son fuentes útiles, pero falibles. El escepticismo examina sus límites; no obliga a concluir que todo sea imposible de conocer. Una buena justificación debe responder a objeciones y alternativas.","Creer que lloverá porque lo soñaste no equivale a una predicción apoyada por un pronóstico contrastable.","1. Formula la creencia.\n2. Pregunta qué la justifica.\n3. Evalúa la fuente.\n4. Considera error y azar.\n5. Ajusta tu confianza.","Compara una creencia basada en intuición con otra basada en evidencia. Explica qué justifica cada una y qué podría refutarlas.","epistemology knowledge evidence justification skepticism","¿Qué pregunta central plantea la epistemología?","Qué podemos conocer y qué justifica nuestras creencias.","Qué diseño de edificio es más bonito.","Qué emoción debemos sentir.","");
 add("philosophy","Consecuencias, deberes y virtudes","Ética normativa","Comparar marcos éticos y justificar decisiones en dilemas con intereses en conflicto.","Consecuencialismo · deontología · virtud · dilema · responsabilidad.","El consecuencialismo evalúa resultados; la deontología considera deberes y límites; la ética de la virtud pregunta qué carácter y hábitos expresan nuestras acciones. Los marcos pueden entrar en tensión. Pensar éticamente exige identificar afectados, consecuencias, derechos y contexto.","Mentir para proteger a alguien puede parecer correcto por sus consecuencias, pero plantea preguntas sobre confianza y deber de honestidad.","1. Describe el dilema.\n2. Identifica afectados.\n3. Analiza consecuencias.\n4. Examina deberes y virtudes.\n5. Justifica qué criterio priorizas.","Analiza un dilema ficticio desde los tres marcos y explica dónde discrepan.","normative ethics consequentialism deontology virtue ethics","¿Qué pregunta prioriza la ética de la virtud?","Qué carácter y hábitos expresa una acción.","Solo qué resultado produce.","Solo si una norma escrita lo permite.","");
 add("philosophy","Libertad, elección y responsabilidad","Existencia y sentido","Explicar cómo libertad y responsabilidad operan dentro de circunstancias reales.","Existencialismo · elección · responsabilidad · autenticidad · mala fe.","La libertad no significa poder hacerlo todo. Está situada entre límites, circunstancias y consecuencias. Las corrientes existencialistas analizan cómo elegimos cuando no hay instrucciones definitivas. La autenticidad implica asumir la propia elección en vez de fingir que no elegimos; tampoco exige ignorar las condiciones materiales.","No escoger puede mantener una situación. La inacción tiene consecuencias aunque no siempre sea una decisión consciente.","1. Identifica circunstancias.\n2. Distingue lo que controlas.\n3. Reconoce opciones reales.\n4. Examina consecuencias.\n5. Justifica una elección.","Escribe una escena breve donde un personaje elige entre seguridad y autenticidad. Explica qué pierde y qué asume.","existentialism freedom responsibility authenticity philosophical choice","¿La libertad existencial significa ausencia total de límites?","No; se ejerce dentro de circunstancias y con consecuencias.","Sí, significa poder hacer cualquier cosa.","Solo consiste en obedecer deseos inmediatos.","");
 add("philosophy","El absurdo y la rebelión cotidiana","Existencia y sentido","Comprender el absurdo como tensión entre la búsqueda humana de sentido y la ausencia de una respuesta definitiva.","Camus · absurdo · lucidez · rebelión · sentido · Sísifo.","En Camus, el absurdo no es simplemente tristeza ni una excusa para rendirse. Surge del choque entre nuestra necesidad de sentido y un mundo que no ofrece una respuesta final garantizada. Su respuesta explora vivir con lucidez y rebelión, sin inventar certezas para tapar la pregunta.","Sísifo puede imaginarse feliz no porque su condena sea agradable, sino porque la lucidez cambia su relación con ella.","1. Identifica la pregunta de sentido.\n2. Reconoce la falta de respuesta definitiva.\n3. Evita certezas falsas.\n4. Examina la rebelión cotidiana.\n5. Relaciónalo con una decisión.","Interpreta Sísifo como metáfora de una rutina repetida y propone dos lecturas distintas.","Albert Camus absurdism Myth of Sisyphus revolt meaning","¿Dónde nace el absurdo en Camus?","En la tensión entre la búsqueda humana de sentido y el silencio del mundo.","En que toda acción sea inútil por definición.","En que las emociones sean falsas.","");
 add("philosophy","Estoicismo: juicio y control","Filosofías prácticas","Distinguir lo que depende de nuestras decisiones de lo que no controlamos.","Estoicismo · dicotomía del control · juicio · virtud · aceptación.","El estoicismo clásico no propone no sentir ni aguantar cualquier abuso. Invita a examinar juicios y dirigir el esfuerzo hacia decisiones propias. No controlas la reacción ajena, pero puedes trabajar cómo respondes, qué límites pones y qué acción eliges. Aceptar un hecho no significa aprobarlo ni permanecer en peligro.","Una crítica ajena no depende enteramente de ti; decidir si revisas una crítica válida y cómo respondes sí implica tu juicio.","1. Describe el evento.\n2. Separa control y no control.\n3. Examina tu juicio.\n4. Elige una acción coherente.\n5. Revisa el resultado.","Aplica la dicotomía del control a un conflicto ficticio y diferencia aceptación de pasividad.","Stoicism Epictetus dichotomy of control virtue practical philosophy","¿Qué propone la dicotomía del control?","Distinguir lo que depende de nuestra acción de lo que no.","Aceptar pasivamente cualquier situación.","Creer que podemos controlar a otras personas.","");
 add("philosophy","Conciencia e identidad personal","Mente y conciencia","Comparar preguntas filosóficas sobre conciencia, experiencia e identidad a través del tiempo.","Conciencia · experiencia subjetiva · identidad · dualismo · fisicalismo.","La filosofía de la mente pregunta qué significa tener una experiencia, cómo se relaciona la mente con el cuerpo y qué hace que una persona siga siendo la misma. Explicar funciones cerebrales no elimina automáticamente la pregunta por la experiencia subjetiva; tampoco la convierte en algo sobrenatural.","Si alguien pierde recuerdos importantes, ¿su identidad depende de la memoria, del cuerpo, de las relaciones o de una combinación?","1. Define conciencia o identidad.\n2. Compara teorías.\n3. Identifica qué explica cada una.\n4. Busca un caso límite.\n5. Expón qué queda abierto.","Defiende una teoría de identidad personal ante un caso ficticio de pérdida de recuerdos.","philosophy of mind consciousness personal identity mind body","¿Qué estudia la filosofía de la mente?","Conciencia, experiencia y relación entre mente y cuerpo.","Solo la anatomía del cerebro.","Solo las normas sociales.","");
 add("philosophy","Estética: belleza, oscuridad y lo sublime","Estética y arte","Analizar cómo forma, contexto y experiencia participan en el valor artístico.","Estética · forma · gusto · sublime · grotesco · interpretación.","La estética estudia qué entendemos por arte, belleza y experiencia estética. Una obra puede resultar valiosa sin ser agradable: lo grotesco, inquietante o sublime también produce experiencia estética. El gusto personal importa, pero analizar una obra exige describir recursos y efectos.","Una canción pesada puede construir belleza mediante contraste, repetición, tensión y liberación, no a pesar de su agresividad.","1. Describe la forma.\n2. Observa recursos.\n3. Identifica el efecto.\n4. Considera contexto.\n5. Justifica tu lectura.","Analiza una obra oscura que conozcas sin resumirla: describe tres decisiones formales y su efecto.","philosophy aesthetics sublime art beauty dark art","¿Una obra tiene que ser agradable para tener valor estético?","No; puede producir valor mediante lo inquietante, grotesco o sublime.","Sí, si incomoda deja de ser arte.","Solo importa la intención del autor.","");
 route("music","Música · Escucha y creación","♫");
 add("music","Escucha activa y capas sonoras","Escucha y análisis","Identificar capas, funciones y cambios de intensidad sin perder la experiencia global.","Timbre · textura · capas · dinámica · panorama · densidad.","Escuchar activamente significa separar elementos sin perder la experiencia global. Distingue voz, guitarras, bajo, batería, sintetizadores y ambientes. Observa qué instrumento lleva el motivo, cuál sostiene la armonía y cómo cambia la densidad. No se trata de diseccionar hasta matar la canción.","En metalcore, una estrofa puede dejar espacio a la voz y el estribillo abrir guitarras, dobles voces y platos para aumentar energía.","1. Escucha una vez sin analizar.\n2. Identifica capas.\n3. Sigue un instrumento.\n4. Marca cambios.\n5. Describe el efecto.","Elige una canción de tu biblioteca y crea un mapa de capas por secciones, sin copiar letras.","active listening music arrangement timbre texture dynamics layers","¿Qué aporta escuchar por capas?","Reconocer funciones y cambios de cada elemento.","Juzgar la canción solo por la letra.","Eliminar la experiencia emocional.","");
 add("music","Pulso, compás y groove","Ritmo y batería","Reconocer pulso, compás, subdivisión y desplazamientos rítmicos básicos.","Pulso · BPM · compás · subdivisión · síncopa · groove · half-time.","El pulso es la referencia regular; BPM indica su velocidad. El compás organiza pulsos y la subdivisión divide cada pulso. La síncopa desplaza acentos esperados. Un mismo tempo puede sentirse distinto con patrones half-time o doble bombo.","Un riff a 160 BPM puede sentirse más pesado si la caja crea sensación half-time.","1. Marca el pulso.\n2. Cuenta grupos.\n3. Escucha subdivisiones.\n4. Localiza acentos.\n5. Describe el groove.","Cuenta el pulso de dos canciones y compara cómo cambia la sensación aunque el BPM sea parecido.","music rhythm meter BPM subdivision syncopation half time","¿Qué describe el BPM?","La cantidad de pulsos por minuto.","El número de instrumentos.","La tonalidad.","");
 add("music","Armonía, disonancia y tensión","Armonía y emoción","Comprender cómo acordes, intervalos y resolución crean tensión y reposo.","Intervalo · acorde · tonalidad · disonancia · resolución · pedal tone.","La armonía organiza relaciones entre alturas. La disonancia puede generar tensión que se resuelve o se mantiene. No existe una emoción universal fija para cada acorde: el efecto depende de contexto, timbre, ritmo y cultura.","Un pedal tone sostenido bajo acordes cambiantes puede crear tensión sin necesidad de acelerar.","1. Escucha la nota grave.\n2. Identifica cambios armónicos.\n3. Observa estabilidad.\n4. Localiza resolución.\n5. Describe el efecto.","Crea una progresión de cuatro acordes que empiece estable, aumente tensión y cierre con resolución o final abierto.","music harmony intervals dissonance tension resolution composition","¿Qué puede producir una disonancia?","Tensión que puede resolverse o mantenerse deliberadamente.","Una emoción idéntica en todos.","La desaparición del ritmo.","");
 add("music","Motivos, melodía y desarrollo","Composición melódica","Crear un motivo breve y transformarlo sin perder su identidad.","Motivo · frase · contorno · repetición · variación · registro.","Un motivo es una idea musical breve reconocible. Puede desarrollarse mediante repetición, cambio rítmico, inversión, secuencia o variación de registro. Una melodía memorable no necesita muchas notas: necesita dirección y relación entre frases.","Un motivo de cuatro notas puede reaparecer más grave, con otro ritmo o sobre una armonía distinta.","1. Escribe un motivo corto.\n2. Marca su contorno.\n3. Repítelo.\n4. Varía ritmo o registro.\n5. Crea una respuesta.","Inventa un motivo de cuatro notas y tres variaciones para una intro oscura.","music melody motif phrase contour variation composition","¿Qué es un motivo musical?","Una idea breve que puede reconocerse y desarrollarse.","Una canción completa sin repetición.","Un efecto de reverberación.","");
 add("music","Estructura y dinámica metalcore","Arreglo y forma","Analizar cómo secciones, contraste y dinámica construyen un arco emocional.","Intro · verso · estribillo · breakdown · puente · outro · contraste.","La estructura ordena expectativas. El contraste puede venir de densidad, registro, armonía o textura. Un breakdown no funciona solo por ser lento o pesado: necesita preparación, acento y espacio. La dinámica crea recorrido emocional.","Una estrofa contenida prepara un estribillo abierto y un breakdown que recupera un motivo con acentos nuevos.","1. Divide por secciones.\n2. Registra energía.\n3. Marca transiciones.\n4. Identifica motivos que regresan.\n5. Explica el arco.","Dibuja el mapa de una canción metalcore original con cinco secciones y un cambio de energía claro.","metalcore song structure dynamics breakdown arrangement verse chorus","¿Qué hace efectivo un breakdown?","Preparación, espacio y acentos que justifican el impacto.","Que sea siempre la parte más rápida.","Que aparezca sin preparación.","");
 add("music","Guitarras, afinaciones y capas","Instrumentación","Comprender cómo afinación, registro y doblajes cambian peso y claridad.","Afinación · registro · palm mute · doblaje · paneo · frecuencias.","La afinación grave amplía el registro, pero no garantiza contundencia. La claridad depende de interpretación, arreglo, ecualización y espacio entre instrumentos. Doblar guitarras y separarlas en el panorama crea anchura si las tomas están bien ajustadas.","Dos guitarras tocando lo mismo, paneadas a lados opuestos, crean anchura; si el timing difiere demasiado, el ataque pierde definición.","1. Escucha el registro.\n2. Distingue capas.\n3. Observa articulación.\n4. Comprueba espacio frecuencial.\n5. Evalúa claridad.","Diseña un arreglo de dos guitarras para un riff: decide qué toca cada una y qué función cumple.","metal guitar tuning Drop B layering panning palm mute arrangement","¿Qué aporta doblar guitarras y panealas?","Anchura estéreo si las tomas están bien ejecutadas.","Más volumen sin cambios de textura.","Eliminar la necesidad de bajo.","");
 add("music","Mezcla, producción y atmósfera","Producción musical","Reconocer cómo mezcla, espacio, dinámica y efectos construyen atmósfera.","EQ · compresión · reverberación · delay · automatización · headroom.","La producción organiza la relación entre fuentes. La ecualización reparte espacio, la compresión controla dinámica, la reverberación sitúa sonidos y la automatización crea movimiento. Más compresión o volumen no equivalen automáticamente a mejor sonido.","Una voz cercana y seca contrasta con guitarras amplias y reverberadas para crear intimidad frente a grandiosidad.","1. Identifica el elemento principal.\n2. Escucha espacio y profundidad.\n3. Compara dinámica.\n4. Detecta efectos.\n5. Relaciona decisiones con intención.","Describe una mezcla imaginaria para una canción oscura: voz, guitarras, batería y ambiente. Justifica tres decisiones.","music production mixing EQ compression reverb automation dynamics","¿Qué función puede cumplir la reverberación?","Crear sensación de espacio y profundidad.","Aumentar siempre la claridad.","Cambiar la tonalidad.","");
 add("music","Letra, voz lírica y narrativa musical","Composición y letra","Crear una letra original con imagen central, progresión emocional y ritmo verbal.","Voz lírica · imagen · métrica · repetición · contraste · subtexto.","Una letra eficaz no tiene que explicarlo todo. Puede construir una imagen recurrente, dejar contradicciones y reservar la frase más directa para el momento de mayor tensión. El ritmo verbal debe poder cantarse. Estudia recursos de artistas sin copiar sus frases: transforma la técnica en lenguaje propio.","En vez de decir «estoy roto», una voz puede describir una casa que sigue en pie pero ya no tiene ventanas.","1. Define emoción y conflicto.\n2. Elige una imagen central.\n3. Escribe versos concretos.\n4. Diseña un estribillo con giro.\n5. Lee en voz alta.","Escribe una estrofa y un estribillo originales de temática gótica, evitando clichés y explicaciones literales.","songwriting lyric writing imagery narrative voice meter original composition","¿Qué aporta una imagen central a una letra?","Une versos y sugiere emoción sin explicarlo todo.","Sustituye la necesidad de ritmo.","Obliga a rimar cada línea.","");
 add("music","Análisis musical de una canción","Escucha y análisis","Describir cómo letra, arreglo, interpretación y producción colaboran en el efecto de una canción.","Forma · timbre · dinámica · interpretación · motivo · producción · escucha crítica.","El análisis no consiste en decir «me transmite mucho». Identifica decisiones audibles y explica su efecto. Separa gusto personal de descripción: puedes amar un tema y reconocer una mezcla saturada, o no conectar con una canción y describir su construcción con precisión.","Compara una estrofa íntima y un estribillo expansivo: registra cambios de registro vocal, densidad instrumental y espacio.","1. Elige una canción.\n2. Divide sus secciones.\n3. Analiza voz y ritmo.\n4. Analiza armonía y producción.\n5. Justifica el efecto global.","Analiza un tema de tu biblioteca en 250 palabras: estructura, voz, instrumentos, producción y efecto emocional. No transcribas letras.","music analysis metalcore Sleep Token Dayseeker Motionless in White arrangement production","¿Qué diferencia análisis musical de una opinión de gusto?","El análisis señala decisiones audibles y explica sus efectos.","El análisis exige que te guste la canción.","El análisis consiste en resumir la letra.","");
 route("writing","Escritura · Taller creativo","✒");
 add("writing","Imágenes, metáforas y símbolos","Lenguaje e imagen","Convertir emociones abstractas en imágenes concretas y originales.","Imagen sensorial · metáfora · símbolo · motivo · cliché · precisión.","Una imagen literaria transforma una idea abstracta en algo perceptible. La metáfora crea una relación nueva; el símbolo gana significado por repetición y contexto. Evita acumular adjetivos oscuros sin función: una imagen precisa pesa más que cinco palabras dramáticas.","«La habitación olía a lluvia vieja» sugiere abandono mediante un detalle, sin decir que el personaje está triste.","1. Nombra la emoción.\n2. Busca un objeto o sensación.\n3. Relaciónalo de forma inesperada.\n4. Comprueba que encaje.\n5. Elimina adornos redundantes.","Escribe cinco imágenes para representar culpa, deseo o pérdida sin nombrar directamente la emoción.","creative writing imagery metaphor symbolism sensory detail","¿Qué diferencia una imagen eficaz de un cliché?","La imagen concreta aporta una relación precisa y contextual.","La imagen usa muchos adjetivos intensos.","La imagen explica la emoción dos veces.","");
 add("writing","Voz narrativa y punto de vista","Narrativa y voz","Elegir perspectiva narrativa y controlar qué sabe y oculta el lector.","Primera persona · tercera limitada · omnisciencia · focalización · narrador.","El punto de vista decide qué información llega, cuándo y con qué sesgo. La primera persona ofrece intimidad pero limita conocimiento; la tercera limitada sigue la experiencia de un personaje; la omnisciencia permite saltos, pero requiere control. Un narrador puede equivocarse sin que el texto sea incoherente.","Un narrador asegura «no tenía miedo» mientras cuenta cómo evita mirar la puerta: aparece una grieta entre discurso y conducta.","1. Decide quién cuenta.\n2. Define qué sabe.\n3. Limita información.\n4. Mantén perspectiva.\n5. Usa contradicciones con intención.","Cuenta una escena de amenaza en primera persona y tercera limitada. Compara qué cambia.","narrative point of view focalization unreliable narrator creative writing","¿Qué controla la focalización?","La información que el lector recibe desde una perspectiva.","La longitud de cada capítulo.","El género gramatical del protagonista.","");
 add("writing","Personajes con contradicciones","Personaje y psicología narrativa","Diseñar personajes con deseo, miedo, contradicción y decisiones con consecuencias.","Deseo · necesidad · contradicción · agencia · conflicto · arco.","Un personaje no se vuelve profundo por acumular traumas. Necesita deseos concretos, límites, contradicciones y capacidad de decidir. El arco aparece cuando sus decisiones modifican la relación con el conflicto. La complejidad no justifica automáticamente el daño que causa.","Un personaje quiere proteger a otros, pero oculta información para conservar el control. La contradicción genera conflicto sin convertirlo automáticamente en villano.","1. Define qué quiere.\n2. Define qué necesita.\n3. Crea una contradicción.\n4. Ponlo ante una elección.\n5. Muestra el coste.","Diseña un protagonista gótico con deseo, miedo, contradicción y una decisión irreversible.","character development desire flaw contradiction agency narrative arc","¿Qué revela mejor el carácter?","Las decisiones bajo presión y sus consecuencias.","Una lista de adjetivos.","La cantidad de tragedias vividas.","");
 add("writing","Diálogo, subtexto y silencios","Personaje y diálogo","Escribir diálogo donde los personajes persiguen objetivos y ocultan parte de lo que sienten.","Objetivo · conflicto · subtexto · ritmo · interrupción · silencio.","El diálogo no es una transcripción de conversaciones reales. Cada intervención debe acercar, evitar, desafiar, ocultar o cambiar el poder. El subtexto surge cuando las palabras no expresan todo lo que el personaje piensa. El silencio también puede ser respuesta.","«¿Has cenado?» puede ser una forma de preguntar «¿sigues enfadado?» sin atreverse a nombrarlo.","1. Define qué quiere cada personaje.\n2. Decide qué no dirá.\n3. Escribe frases con intención.\n4. Introduce una evasión.\n5. Elimina explicaciones obvias.","Escribe un diálogo de 12 líneas entre dos personajes que se quieren pero evitan hablar de una traición.","dialogue subtext character goals conflict silence creative writing","¿Qué es el subtexto?","El significado implícito que no se expresa literalmente.","La explicación del narrador tras cada frase.","El uso obligatorio de metáforas.","");
 add("writing","Tensión, ritmo y revelación","Estructura y tensión","Controlar la tensión mediante expectativa, obstáculos, información y pausas.","Pregunta dramática · escalada · obstáculo · anticipación · revelación · ritmo.","La tensión aparece cuando el lector entiende qué puede perderse y desconoce cómo terminará. No necesitas acción constante: una puerta que no se abre puede generar tensión si el contexto importa. Las revelaciones funcionan mejor cuando reordenan pistas previas.","Una llamada sin respuesta pesa más si antes estableciste por qué ese personaje siempre contesta.","1. Define qué está en juego.\n2. Retrasa una respuesta.\n3. Añade un obstáculo.\n4. Dosifica información.\n5. Revela algo que cambie el sentido.","Escribe una escena donde alguien espera una llamada y el verdadero conflicto se revela al final.","narrative tension suspense pacing anticipation revelation storytelling","¿Qué necesita la tensión narrativa?","Algo en juego y una incertidumbre significativa.","Acción continua sin consecuencias.","Ocultar toda la información.","");
 add("writing","Escenas, atmósfera y mundo","Construcción de escenas","Construir escenas con objetivo, obstáculo, cambio y detalles sensoriales selectivos.","Escena · objetivo · obstáculo · giro · atmósfera · worldbuilding.","Una escena debe modificar algo: información, relación, peligro o decisión. La atmósfera nace de detalles concretos elegidos, no de describir cada objeto. El worldbuilding funciona mejor cuando aparece ligado a necesidades y conflictos.","Un templo abandonado puede revelarse por la cera reciente en el suelo, no por tres párrafos de historia.","1. Define objetivo.\n2. Introduce obstáculo.\n3. Elige dos detalles sensoriales.\n4. Crea un cambio.\n5. Termina con consecuencia.","Escribe una escena de fantasía oscura en un lugar aparentemente vacío que revele que alguien estuvo allí hace poco.","scene structure atmosphere sensory details worldbuilding dark fantasy","¿Qué debe cambiar en una escena eficaz?","Algo en la información, relación, peligro o decisión.","Nada; solo describe un lugar.","La biografía completa del mundo.","");
 add("writing","Revisión y estilo","Edición y reescritura","Revisar un texto por capas: estructura, claridad, ritmo y precisión verbal.","Revisión global · continuidad · ritmo · redundancia · edición de línea.","Corregir cada palabra mientras aún no sabes qué ocurre es gastar esfuerzo en una estructura que quizá desaparezca. Revisa primero propósito y escenas; después continuidad y claridad; al final ritmo, sonido y elección léxica. El estilo también emerge de lo que eliminas.","Si tres frases describen la misma tristeza, conserva la que produce una imagen concreta y deja espacio al lector.","1. Lee sin editar.\n2. Resume la intención.\n3. Revisa estructura.\n4. Corta redundancias.\n5. Ajusta ritmo y sonido.","Reescribe un párrafo de 120 palabras reduciéndolo a 80 sin perder imagen ni intención.","creative writing revision editing clarity rhythm concision","¿En qué orden conviene revisar un borrador?","Primero estructura y sentido; después claridad y estilo.","Primero cada coma sin revisar el contenido.","Solo cambiar adjetivos por sinónimos.","");
 add("writing","Poesía breve y ritmo verbal","Poesía y voz","Escribir un poema breve donde ritmo, imagen y giro final trabajen juntos.","Verso libre · pausa · repetición · encabalgamiento · voz · cierre.","La poesía no exige rimar. El verso libre también tiene ritmo: longitud, pausas, sonidos, repeticiones y cortes. Un cierre eficaz puede transformar una imagen anterior. Evita explicar el significado después de construirlo: confía en la relación entre imágenes.","Tres versos cortos tras una estrofa larga pueden crear una caída seca y deliberada.","1. Elige una imagen central.\n2. Escribe sin buscar rima.\n3. Lee en voz alta.\n4. Ajusta pausas.\n5. Busca un cierre que transforme la imagen.","Escribe un poema de 8-12 versos sobre una promesa rota sin utilizar las palabras tristeza, dolor o amor.","poetry writing free verse rhythm imagery line breaks","¿Qué organiza el ritmo en verso libre?","Longitud, pausas, sonidos, repeticiones y cortes.","La rima consonante obligatoria.","El número fijo de sílabas en todos los versos.","");
 add("writing","Bloqueo creativo y generación de ideas","Proceso creativo","Usar restricciones, asociaciones y prototipos para producir material creativo sin esperar inspiración.","Restricción · asociación · escritura libre · prototipo · selección · revisión.","La creatividad no depende solo de una chispa. Las restricciones reducen decisiones y ayudan a empezar. Generar ideas y evaluarlas son fases distintas: si juzgas cada frase mientras nace, cortas la exploración. Después seleccionas, combinas y revisas.","Escribir una escena usando solo una habitación, dos personajes y un objeto puede producir más tensión que abrir un mundo entero.","1. Define una restricción.\n2. Genera material sin editar.\n3. Selecciona una idea.\n4. Crea un prototipo breve.\n5. Revisa con un objetivo.","Genera tres premisas para una historia oscura usando el mismo objeto como símbolo y elige la más prometedora.","creative process brainstorming constraints divergent convergent thinking","¿Por qué separar generación y evaluación de ideas?","Para permitir explorar antes de descartar posibilidades.","Para evitar revisar cualquier texto.","Porque todas las ideas son igual de buenas.","");
 route("interpretation","Interpretación · Textos y símbolos","⌘");
 add("interpretation","Voz lírica, imagen y conflicto","Lectura poética","Interpretar un poema distinguiendo voz lírica, imágenes y tensión central.","Voz lírica · hablante · imagen · campo semántico · tono · conflicto.","No confundas automáticamente al autor con la voz que habla. Un poema puede construir una máscara, contradicción o escena ficticia. Empieza por lo que aparece: imágenes, repeticiones, cambios de tono y silencios. Después formula una interpretación apoyada en esos detalles.","Un poema sobre una casa vacía puede hablar de pérdida, identidad o memoria. La lectura debe justificar qué interpretación encaja mejor.","1. Lee por impresión.\n2. Identifica quién habla.\n3. Subraya imágenes.\n4. Detecta contradicciones.\n5. Formula una tesis con evidencias.","Interpreta un poema breve de dominio público o uno propio: explica voz, imagen central y conflicto en 5-7 líneas.","poetry analysis speaker imagery tone conflict close reading","¿Por qué no debemos identificar automáticamente voz lírica y autor?","Porque la voz puede ser una construcción literaria distinta del autor.","Porque todos los poemas son autobiográficos.","Porque el poema no tiene hablante.","");
 add("interpretation","Metáfora, símbolo y leitmotiv","Lectura simbólica","Distinguir metáfora puntual, símbolo contextual y motivo recurrente.","Metáfora · símbolo · leitmotiv · recurrencia · transformación · contexto.","Una metáfora relaciona elementos; un símbolo adquiere significado dentro de una obra; un leitmotiv es un motivo que regresa y puede transformarse. No existe un diccionario universal de símbolos: una rosa no significa siempre amor ni una sombra siempre maldad.","Una llave que aparece primero como promesa y al final como amenaza cambia de valor por el recorrido narrativo.","1. Localiza la imagen.\n2. Observa dónde aparece.\n3. Registra variaciones.\n4. Relaciónala con el conflicto.\n5. Evita significados automáticos.","Analiza un símbolo recurrente en una historia de fantasía oscura y explica cómo cambia.","literary symbolism metaphor leitmotif motif close reading","¿Qué convierte un objeto en símbolo dentro de una obra?","La red de asociaciones que construye su contexto y recurrencia.","Un significado universal fijo.","Que el objeto sea antiguo.","");
 add("interpretation","Ritmo, sonido y forma poética","Forma y musicalidad","Relacionar ritmo, repetición y sonido con el sentido de un poema.","Métrica · ritmo · aliteración · asonancia · encabalgamiento · pausa.","La forma no es decoración. El ritmo puede acelerar, detener o tensar una lectura. La repetición crea insistencia; la aliteración dirige la atención al sonido; el encabalgamiento desplaza la pausa esperada. No hace falta contar sílabas en todos los poemas para analizar musicalidad.","Una frase breve aislada tras varios versos largos puede producir un corte emocional.","1. Lee en voz alta.\n2. Marca pausas.\n3. Observa repeticiones.\n4. Relaciona sonido y tono.\n5. Explica el efecto.","Escribe cuatro versos libres con repetición deliberada y explica el efecto rítmico buscado.","poetry rhythm sound devices enjambment alliteration form analysis","¿Qué efecto puede producir el encabalgamiento?","Desplazar la pausa y crear continuidad o tensión.","Convertir el poema en prosa automáticamente.","Eliminar el ritmo.","");
 add("interpretation","Narrador, focalización y fiabilidad","Lectura narrativa","Detectar límites de información y señales de narrador no fiable.","Narrador · focalización · omisión · contradicción · fiabilidad · ironía.","Un narrador no fiable no es simplemente alguien que miente. Puede interpretar mal, omitir, justificar o desconocer datos. El lector compara su versión con contradicciones, acciones y otros testimonios. La incertidumbre debe estar construida, no ser un truco sin pistas.","Un personaje afirma que no teme a nadie, pero evita un lugar y cambia de tema cuando se lo mencionan.","1. Identifica quién narra.\n2. Anota qué sabe.\n3. Busca contradicciones.\n4. Compara palabras y acciones.\n5. Formula una hipótesis prudente.","Analiza un narrador ficticio que parece fiable al principio y deja tres pistas de que su versión es parcial.","unreliable narrator focalization narrative reliability close reading","¿Qué puede hacer que un narrador sea no fiable?","Limitaciones, omisiones o contradicciones entre su versión y las pistas.","Que narre en primera persona.","Que el lector no conozca su nombre.","");
 add("interpretation","Personajes, motivaciones y subtexto","Lectura de personajes","Inferir motivaciones narrativas usando decisiones, contradicciones y contexto.","Deseo · miedo · objetivo · subtexto · agencia · arco.","No diagnostiques personajes como si fueran pacientes reales. Analiza su función narrativa: qué desean, qué temen, qué ocultan y qué decisiones toman. Una contradicción puede crear complejidad sin justificar automáticamente el daño que causan.","Un personaje que protege a su rival puede actuar por culpa, estrategia, afecto o necesidad de control. El texto ofrece pistas para priorizar lecturas.","1. Registra acciones.\n2. Identifica objetivo.\n3. Observa lo que evita.\n4. Contrasta discurso y conducta.\n5. Justifica tu hipótesis.","Elige un personaje de una obra que conozcas y explica dos motivaciones posibles con evidencias de escenas.","character analysis motivation subtext narrative agency interpretation","¿En qué debe basarse una interpretación de motivaciones?","En acciones, contradicciones y contexto narrativo.","En una etiqueta psicológica aislada.","En la opinión de fans solamente.","");
 add("interpretation","Gótico, fantasía oscura y atmósfera","Géneros y atmósfera","Reconocer recursos del gótico y la fantasía oscura sin reducirlos a estética superficial.","Espacio liminal · ruina · doble · secreto · sublime · decadencia · amenaza.","Lo gótico utiliza espacios, secretos, herencias, dobles y amenazas para materializar conflictos. La fantasía oscura combina lo sobrenatural con dilemas morales y consecuencias. La oscuridad funciona cuando afecta a la historia, no cuando todo está cubierto de adjetivos negros.","Un castillo en ruinas puede representar una institución que sobrevive después de perder aquello que la legitimaba.","1. Identifica el espacio.\n2. Busca secreto o prohibición.\n3. Observa el doble o amenaza.\n4. Relaciona atmósfera y conflicto.\n5. Evita confundir tono y tema.","Analiza una escena gótica de un libro, manga o anime: señala espacio, amenaza y conflicto simbólico.","gothic literature dark fantasy atmosphere symbolism sublime genre","¿Qué vuelve funcional un recurso gótico?","Que la atmósfera materialice un conflicto o secreto.","Que aparezcan muchos castillos y sangre.","Que todos hablen de forma solemne.","");
 add("interpretation","Manga y narrativa visual","Narrativa visual","Interpretar cómo encuadre, secuencia, silencio y composición construyen significado en manga.","Viñeta · plano · composición · gutter · ritmo visual · página.","El manga narra con palabras e imágenes. El espacio entre viñetas permite inferir acciones y tiempo; el tamaño de plano regula distancia emocional; la composición dirige la mirada. Una página puede ralentizar un instante mediante repetición o ampliar impacto con una viñeta dominante.","Una secuencia de primeros planos de manos puede comunicar tensión sin explicar lo que siente el personaje.","1. Observa la página completa.\n2. Sigue el orden de lectura.\n3. Analiza planos.\n4. Mira espacios y silencios.\n5. Relaciona forma y efecto.","Analiza una página de manga que tengas disponible: explica cómo tres decisiones visuales construyen tensión.","manga visual storytelling panel composition gutter pacing visual literacy","¿Qué función puede tener el espacio entre viñetas?","Permitir que el lector reconstruya tiempo o acción entre imágenes.","Decorar el margen sin función narrativa.","Sustituir siempre el texto.","");
 add("interpretation","Intertextualidad y arquetipos","Lectura comparada","Comparar arquetipos y referencias sin asumir que toda semejanza es una influencia.","Intertextualidad · arquetipo · alusión · adaptación · reescritura · contexto.","Una obra dialoga con otras mediante referencias, arquetipos, imágenes o estructuras. Reconocer una alusión amplía el sentido, pero no significa que toda semejanza sea intencional. Compara funciones, no solo nombres o apariencias.","Dos personajes que desafían a una autoridad pueden compartir un arquetipo, pero sus motivos y consecuencias pueden ser opuestos.","1. Describe la semejanza.\n2. Busca diferencias.\n3. Comprueba contexto.\n4. Distingue influencia y coincidencia.\n5. Explica qué cambia.","Compara un arquetipo de anime con uno de literatura fantástica: una semejanza y dos diferencias.","intertextuality adaptation archetypes comparative literature narrative","¿Qué exige una comparación intertextual sólida?","Explicar semejanzas, diferencias y contexto sin asumir influencia automática.","Encontrar dos nombres parecidos.","Decir que todas las historias son iguales.","");

 add("english","Narrar experiencias con tiempos verbales","Gramática y precisión","Elegir past simple, past continuous y present perfect según la relación temporal del mensaje.","Past simple · past continuous · present perfect · time markers.","Past simple presenta un hecho terminado; past continuous sitúa una acción en desarrollo; present perfect conecta una experiencia pasada con el presente. No elijas un tiempo por traducir palabra a palabra: el contexto decide.","I was walking home when it started raining. I have never visited London.","1. Sitúa el momento.\n2. Decide si está terminado.\n3. Distingue acción en curso y evento.\n4. Comprueba conexión con el presente.\n5. Lee la frase completa.","Cuenta una experiencia de 8 frases usando dos tiempos pasados y una conexión con el presente.","English B1 past simple past continuous present perfect narrative","¿Qué expresa normalmente past continuous?","Una acción en desarrollo en un momento pasado.","Una experiencia conectada necesariamente con el presente.","Una acción futura planificada.","");
 add("japanese","Verbos y adjetivos en presente y pasado","Gramática básica","Formar enunciados sencillos con verbos y adjetivos en formas afirmativa y negativa.","Forma diccionario · ます · ません · でした · くない · かった.","En japonés, verbos y adjetivos siguen patrones distintos. La forma ます es cortés; los adjetivos い y な no se comportan igual. Aprende frases completas y contrasta afirmación, negación y pasado para evitar memorizar reglas sin uso.","高いです (es caro/alto), 高くないです (no es caro/alto), 高かったです (era/fue caro/alto).","1. Identifica tipo de palabra.\n2. Elige registro.\n3. Aplica la forma adecuada.\n4. Comprueba tiempo y negación.\n5. Lee en voz alta.","Escribe seis frases sobre objetos, comida y actividades: afirmativa, negativa y pasada.","Japanese beginner verb adjective conjugation polite past negative","¿Qué forma negativa cortés corresponde a un adjetivo い como 高い?","高くないです.","高いません.","高かったないです.","");
 add("german","Akkusativ y Dativ en contexto","Gramática y casos","Distinguir acusativo y dativo en estructuras frecuentes y preposiciones básicas.","Kasus · objeto directo · objeto indirecto · Wechselpräpositionen.","El acusativo suele marcar el objeto directo y el dativo aparece con determinados verbos, objetos indirectos y preposiciones. Aprende verbos y preposiciones con ejemplos; algunas preposiciones cambian de caso según movimiento o ubicación.","Ich sehe den Mann (acusativo). Ich helfe dem Mann (dativo).","1. Localiza el verbo.\n2. Aprende si exige caso.\n3. Identifica función.\n4. Revisa artículo.\n5. Comprueba preposición.","Completa seis frases con artículos en acusativo o dativo y explica por qué.","German accusative dative cases beginner grammar","¿Qué caso exige normalmente helfen?","Dativo.","Acusativo.","Genitivo.","");
 add("marketing","Posicionamiento y diferenciación de marca","Estrategia y mercado","Construir un posicionamiento claro a partir de público, categoría, beneficio y diferencia demostrable.","Posicionamiento · propuesta de valor · categoría · diferenciación · prueba.","El posicionamiento es el lugar que una marca busca ocupar frente a alternativas. Una diferencia útil debe importar al cliente y poder sostenerse. «Calidad e innovación» no diferencia si todas las marcas lo dicen.","Una tienda local puede posicionarse por asesoramiento experto y reparación, no por afirmar que tiene «los mejores productos».","1. Define público y categoría.\n2. Identifica alternativas.\n3. Elige un beneficio relevante.\n4. Busca una diferencia verificable.\n5. Redacta una promesa clara.","Crea una frase de posicionamiento para una marca de ropa alternativa y aporta una prueba concreta.","brand positioning value proposition differentiation evidence marketing","¿Qué hace defendible una propuesta de posicionamiento?","Un beneficio relevante y una diferencia demostrable.","Una frase grandilocuente sin pruebas.","Intentar atraer a todos los públicos.","");
 add("web","JavaScript y comportamiento de interfaz","Desarrollo y publicación","Explicar cómo eventos, estado y manipulación del DOM producen interfaces interactivas.","DOM · event listener · estado · validación · renderizado · accesibilidad.","JavaScript conecta la interacción con el contenido. Un evento comunica que ocurrió una acción; el código actualiza el estado y refleja el cambio. La validación debe orientar al usuario y no depender solo del navegador.","Al pulsar «Añadir», el programa valida el texto, actualiza una lista y muestra el nuevo elemento sin recargar la página.","1. Identifica el evento.\n2. Lee los datos.\n3. Valida.\n4. Actualiza el estado.\n5. Renderiza y anuncia el cambio.","Diseña la lógica de una lista de tareas: añadir, marcar y eliminar, indicando qué evento activa cada acción.","JavaScript DOM event listeners state management form validation","¿Qué hace un event listener?","Ejecuta una función cuando ocurre un evento concreto.","Cambia automáticamente el CSS sin lógica.","Sustituye la estructura HTML.","");
 add("reasoning","Evaluar fuentes y estudios","Probabilidad y evidencia","Valorar una fuente según método, muestra, medidas, sesgos y límites de inferencia.","Diseño · muestra · variable · sesgo · replicación · revisión sistemática.","Una fuente no es fiable solo por tener aspecto académico o muchas citas. Pregunta quién participó, cómo se midió, qué diseño se usó y qué limitaciones reconocen. Un estudio observacional puede detectar asociaciones, pero suele tener límites para inferir causalidad.","Un estudio con veinte voluntarios puede sugerir una hipótesis, pero no representar automáticamente a toda la población.","1. Comprueba autoría y publicación.\n2. Identifica diseño y muestra.\n3. Revisa medidas.\n4. Busca limitaciones.\n5. Compara con otras evidencias.","Usa NOESIS para localizar dos estudios sobre un tema y compara muestra, método y limitaciones.","research methods source evaluation sample bias systematic review evidence","¿Qué permite inferir con más cautela un estudio observacional?","Asociaciones, no causalidad por sí sola.","Que una variable causa necesariamente otra.","Que el resultado vale para toda población.","");
 add("organization","Recuperación activa y repetición espaciada","Hábitos y aprendizaje","Diseñar repasos que midan recuerdo y distribuyan la práctica en el tiempo.","Recuperación activa · espaciamiento · dificultad deseable · feedback · consolidación.","Releer produce familiaridad, pero no siempre recuperación. Intentar recordar antes de mirar obliga a reconstruir la información y revela lagunas. Distribuir sesiones permite practicar cuando el recuerdo empieza a debilitarse.","Después de estudiar, responde tres preguntas sin mirar; revisa errores y vuelve a intentarlo mañana y dentro de varios días.","1. Estudia un bloque pequeño.\n2. Cierra el material.\n3. Recupera sin mirar.\n4. Corrige con feedback.\n5. Programa el siguiente repaso.","Diseña un calendario 1-3-7 días para una lección y crea una pregunta de recuperación para cada repaso.","retrieval practice spaced repetition learning science memory","¿Qué distingue recuperación activa de relectura?","Intentar recordar sin consultar el material primero.","Volver a leer con más colores.","Repetir sin feedback.","");
 add("commerce","Experiencia de cliente y posventa","Atención y venta","Mapear el recorrido del cliente y resolver incidencias con comunicación y seguimiento claros.","Customer journey · puntos de contacto · satisfacción · reclamación · posventa.","La experiencia empieza antes de la compra y continúa después. Cada punto de contacto puede facilitar o complicar la decisión. Una reclamación requiere escuchar, comprobar hechos, explicar opciones y cumplir lo prometido. La posventa detecta problemas recurrentes.","Una devolución clara puede conservar la confianza incluso cuando el producto no encaja.","1. Dibuja etapas del recorrido.\n2. Identifica fricciones.\n3. Define información útil.\n4. Diseña respuesta a incidencias.\n5. Mide satisfacción.","Crea un recorrido de cliente para una tienda online y resuelve una reclamación ficticia con pasos verificables.","customer journey retail after sales service complaint handling","¿Qué debe incluir una buena gestión de reclamación?","Escucha, comprobación, opciones claras y seguimiento.","Discutir para demostrar que la tienda tiene razón.","Prometer una solución imposible.","");
 add("professional","Captación ética y gestión de clientes","Freelance y clientes","Conseguir clientes mediante propuesta de valor, prueba de trabajo y seguimiento respetuoso.","Prospección · portfolio · propuesta · cualificación · seguimiento · confianza.","La captación profesional no consiste en enviar mensajes masivos. Identifica negocios con una necesidad observable, prepara una muestra relevante y explica qué resultado puedes aportar. Cualifica el encaje antes de prometer. Un seguimiento breve es distinto de insistir cuando alguien no responde.","Una auditoría breve de la web de un comercio puede demostrar criterio antes de proponer un rediseño.","1. Define cliente ideal.\n2. Detecta una necesidad real.\n3. Prepara evidencia de capacidad.\n4. Formula propuesta concreta.\n5. Haz seguimiento con límite.","Redacta un primer contacto para un pequeño comercio basado en una mejora real, sin prometer resultados imposibles.","freelance client acquisition ethical outreach portfolio value proposition","¿Qué mejora la calidad de una propuesta comercial?","Relacionarla con una necesidad concreta y demostrar capacidad.","Enviar el mismo mensaje a cientos de negocios.","Prometer ventas garantizadas.","");
 add("fitness","Movilidad, rango de movimiento y técnica","Movilidad y técnica","Distinguir movilidad, flexibilidad y control para elegir ejercicios adecuados.","Movilidad · flexibilidad · estabilidad · rango de movimiento · control motor.","La movilidad combina rango de movimiento y capacidad de controlarlo. La flexibilidad describe la capacidad de tejidos para alargarse, pero no garantiza control activo. La técnica depende de anatomía, carga, fatiga y objetivo. No fuerces rangos dolorosos.","Una sentadilla puede requerir ajustar anchura, profundidad o elevación de talones según movilidad y proporciones individuales.","1. Observa el movimiento sin carga.\n2. Detecta compensaciones.\n3. Ajusta rango y posición.\n4. Añade carga gradualmente.\n5. Detente ante dolor agudo.","Graba un movimiento sencillo sin carga y describe dos ajustes técnicos que probarías sin forzar dolor.","mobility flexibility range of motion motor control resistance training technique","¿Qué distingue movilidad de flexibilidad?","La movilidad incluye control activo del rango de movimiento.","Son exactamente lo mismo.","La flexibilidad mide fuerza máxima.","");
 add("psychology","Motivación, metas y autorregulación","Motivación y hábitos","Distinguir motivación fluctuante de sistemas de autorregulación que facilitan actuar.","Motivación intrínseca · extrínseca · metas · autoeficacia · intención de implementación.","La motivación fluctúa y no es una fuente estable de energía. La autorregulación conecta metas con acciones: planificar cuándo y dónde, observar resultados y ajustar. La autoeficacia es la creencia de poder ejecutar una acción concreta y puede cambiar con experiencia y apoyo.","«Mejorar inglés» es vago. «Después de merendar, practicaré 15 minutos de speaking» define señal y conducta.","1. Elige una meta concreta.\n2. Define una acción pequeña.\n3. Asóciala a una señal.\n4. Registra lo que ocurre.\n5. Ajusta sin convertir un fallo en identidad.","Diseña un hábito de aprendizaje con señal, acción, barrera probable y plan alternativo.","motivation self regulation implementation intentions self efficacy psychology","¿Qué aporta una intención de implementación?","Vincula una situación concreta con una acción prevista.","Garantiza motivación constante.","Elimina cualquier obstáculo.","");
 add("psychology","Atribución y lectura social","Cognición social","Distinguir hechos, atribuciones e inferencias sobre la conducta de otras personas.","Atribución causal · sesgo actor-observador · expectativas · ambigüedad · perspectiva.","La cognición social estudia cómo interpretamos a otras personas. Un comportamiento aislado rara vez revela una intención con certeza. Tendemos a explicar la conducta ajena por rasgos y la propia por circunstancias, aunque el contexto puede cambiar esa lectura. Las expectativas influyen en qué señales atendemos.","Un mensaje breve puede deberse a prisa, cansancio, estilo comunicativo o distancia. Sin más datos, no puedes tratar una explicación como un hecho.","1. Escribe lo observable.\n2. Separa la inferencia.\n3. Enumera alternativas.\n4. Busca información relevante.\n5. Actualiza la interpretación.","Analiza un caso ficticio de malentendido y presenta tres explicaciones compatibles con los hechos.","social cognition attribution bias expectations ambiguity psychology","¿Qué diferencia un hecho de una atribución?","El hecho describe lo observado; la atribución interpreta su causa o intención.","Son exactamente lo mismo.","La atribución siempre es correcta.","");


 const readingSamples=[
  {title:"La casa que aprendió a esperar",text:"La casa llevaba veinte años cerrada, pero cada noche alguien encendía una lámpara en el piso superior. Nadie veía entrar a nadie. En la mesa seguía habiendo dos tazas: una limpia, otra cubierta de polvo. El pueblo decía que allí vivía un fantasma. La niña que cruzó el jardín una madrugada descubrió que la luz no venía de una habitación, sino de un espejo orientado hacia la luna."},
  {title:"La llave",text:"La llave apareció en el bolsillo del rey el día de su coronación. No abría ninguna puerta del palacio. El herrero juró no haberla fabricado; el sacerdote aseguró que era una señal. El rey la guardó bajo la lengua durante años, hasta que olvidó cómo pronunciar su propio nombre. La puerta que abría no estaba en el castillo."},
  {title:"Inventario de una ausencia",text:"Queda el vaso con la marca de tus labios, la silla que nadie mueve y el ruido del ascensor deteniéndose en nuestro piso. Queda la costumbre, que es una forma torpe de memoria. No queda tu voz. Sin embargo, cada vez que llueve, la casa pronuncia algo que se parece demasiado a tu nombre."},
  {title:"El testigo",text:"No vi a nadie entrar en la torre. Lo escribo porque me lo han preguntado tres veces y porque la puerta estaba cerrada cuando llegué. Es cierto que la escalera tenía barro fresco y que alguien había dejado una vela encendida junto a mi cama. Pero eso no demuestra nada. Yo nunca he subido al último piso. No desde aquella noche."},
  {title:"La promesa del cuervo",text:"El cuervo regresó con un hilo rojo atado a la pata. La muchacha reconoció el nudo: era el que su hermano hacía cuando mentía. Lo siguió hasta el bosque, donde los árboles crecían inclinados hacia una iglesia sin campanas. En el altar encontró una carta escrita con su letra. La fecha era de mañana."},
  {title:"La habitación",text:"La habitación no era oscura; estaba llena de luz, pero ninguna superficie la devolvía. En el centro había una silla mirando a la pared. Cada noche, el protagonista soñaba que alguien se sentaba allí y le preguntaba por qué seguía fingiendo que no recordaba. Cada mañana, la silla aparecía un poco más cerca de la cama."},
  {title:"Página muda",text:"Viñeta 1: una mano sostiene una corona rota. Viñeta 2: el personaje mira fuera de plano. Viñeta 3: un primer plano del pulgar, manchado de sangre. Viñeta 4: una sala vacía, con la corona en el suelo. No hay diálogo. En la última viñeta, una sombra ocupa el lugar donde antes estaba el personaje."},
  {title:"Dos versiones del mismo héroe",text:"En la primera crónica, el héroe abrió las puertas para salvar a la ciudad. En la segunda, las abrió para que el enemigo entrara y destruyera el archivo real. Ambas coinciden en el gesto, la hora y el número de muertos. Solo difieren en quién escribió la historia y en qué nombre aparece grabado sobre la estatua."}
 ];
 readingSamples.forEach((sample,i)=>{const unit=LESSONS.interpretation.units[i];if(unit){unit.readingTitle=sample.title;unit.reading=sample.text;unit.readingSource="Fragmento original creado para ASCENSION";}});

})();
